DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 4;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _card_stats_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'card_stats recompute: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _card_stats_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'antiquity' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'fortification' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'cultural_influence' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'mystery' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'legacy' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'total_power' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'rarity_score' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'rarity_tier' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'category_group' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR p.old_value IS NULL OR p.new_value IS NULL OR length(p.new_value) > 50
                WHEN 'civilization' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR p.old_value IS NULL OR p.new_value IS NULL OR length(p.new_value) > 100
                WHEN 'empires' THEN p.new_value::jsonb IS NOT DISTINCT FROM p.old_value::jsonb OR p.old_value IS NULL OR p.new_value IS NULL
                WHEN 'empire_count' THEN p.new_value::integer IS NOT DISTINCT FROM p.old_value::integer OR p.old_value IS NULL OR p.new_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'card_stats recompute: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _card_stats_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'antiquity' THEN t.antiquity IS DISTINCT FROM p.old_value::integer
                WHEN 'fortification' THEN t.fortification IS DISTINCT FROM p.old_value::integer
                WHEN 'cultural_influence' THEN t.cultural_influence IS DISTINCT FROM p.old_value::integer
                WHEN 'mystery' THEN t.mystery IS DISTINCT FROM p.old_value::integer
                WHEN 'legacy' THEN t.legacy IS DISTINCT FROM p.old_value::integer
                WHEN 'total_power' THEN t.total_power IS DISTINCT FROM p.old_value::integer
                WHEN 'rarity_score' THEN t.rarity_score IS DISTINCT FROM p.old_value::integer
                WHEN 'rarity_tier' THEN t.rarity_tier IS DISTINCT FROM p.old_value::integer
                WHEN 'category_group' THEN t.category_group IS DISTINCT FROM p.old_value::character varying
                WHEN 'civilization' THEN t.civilization IS DISTINCT FROM p.old_value::character varying
                WHEN 'empires' THEN t.empires IS DISTINCT FROM p.old_value::jsonb
                WHEN 'empire_count' THEN t.empire_count IS DISTINCT FROM p.old_value::integer
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'card_stats recompute: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row undos a value this lane owns (old value)
    SELECT count(*) INTO bad FROM _card_stats_plan p
     WHERE CASE p.column_name
                WHEN 'rarity_tier' THEN p.old_value NOT IN ('1', '2', '3', '4', '5')
                WHEN 'category_group' THEN p.old_value NOT IN ('Burial & Death', 'Fortifications', 'Infrastructure', 'Megalithic', 'Monuments', 'Other', 'Religious', 'Rock & Cave', 'Settlements', 'Water & Ports')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'card_stats recompute: % planned row(s) undo a value this lane does not own', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _card_stats_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (md5(concat_ws('|', coalesce(u.site_type, '<NULL>'), coalesce(u.period_name, '<NULL>'), coalesce(u.period_start::text, '<NULL>'), coalesce(u.period_end::text, '<NULL>'), coalesce(u.country, '<NULL>'), coalesce(u.lat::text, '<NULL>'), coalesce(u.lon::text, '<NULL>'), md5(coalesce(u.description, '<NULL>')), md5(coalesce(u.source_url, '<NULL>')), md5(coalesce(u.thumbnail_url, '<NULL>')), (SELECT count(*) || ':' || coalesce(md5(string_agg(coalesce(s.content_type, '<NULL>') || '/' || coalesce(s.content_source, '<NULL>'), ',' ORDER BY s.id)), '') FROM site_content_links s WHERE s.site_id = u.id), (SELECT count(*)::text FROM wiki_images w WHERE w.site_id = u.id), (SELECT count(*)::text FROM site_likes k WHERE k.site_id = u.id), (SELECT count(*)::text FROM site_bookmarks b WHERE b.site_id = u.id), (SELECT md5(string_agg(coalesce(x.site_type, '<NULL>') || '/' || coalesce(x.period_name, '<NULL>'), ',' ORDER BY x.id)) FROM unified_sites x WHERE x.source_id = 'ancient_nerds')))) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'card_stats recompute: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _card_stats_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'P6/card-stats-recompute', '2026-10-04f_mechanical-card-stats-rollback', r.change_key, 'authoritative', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'card_stats recompute: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _card_stats_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'antiquity' THEN t.antiquity IS DISTINCT FROM p.new_value::integer
                WHEN 'fortification' THEN t.fortification IS DISTINCT FROM p.new_value::integer
                WHEN 'cultural_influence' THEN t.cultural_influence IS DISTINCT FROM p.new_value::integer
                WHEN 'mystery' THEN t.mystery IS DISTINCT FROM p.new_value::integer
                WHEN 'legacy' THEN t.legacy IS DISTINCT FROM p.new_value::integer
                WHEN 'total_power' THEN t.total_power IS DISTINCT FROM p.new_value::integer
                WHEN 'rarity_score' THEN t.rarity_score IS DISTINCT FROM p.new_value::integer
                WHEN 'rarity_tier' THEN t.rarity_tier IS DISTINCT FROM p.new_value::integer
                WHEN 'category_group' THEN t.category_group IS DISTINCT FROM p.new_value::character varying
                WHEN 'civilization' THEN t.civilization IS DISTINCT FROM p.new_value::character varying
                WHEN 'empires' THEN t.empires IS DISTINCT FROM p.new_value::jsonb
                WHEN 'empire_count' THEN t.empire_count IS DISTINCT FROM p.new_value::integer
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'card_stats recompute: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _card_stats_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-10-04f_mechanical-card-stats-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'card_stats recompute: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-10-04f_mechanical-card-stats-rollback'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('antiquity', 'fortification', 'cultural_influence', 'mystery', 'legacy', 'total_power', 'rarity_score', 'rarity_tier', 'category_group', 'civilization', 'empires', 'empire_count'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'card_stats recompute: this run stamp journalled % row(s) outside card_stats.(antiquity, fortification, cultural_influence, mystery, legacy, total_power, rarity_score, rarity_tier, category_group, civilization, empires, empire_count)', bad;
    END IF;

    RAISE NOTICE 'card_stats recompute: % of % planned cell(s) changed and journalled over 1 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK of the reversal: the reversal must leave nothing behind either
WITH planned(site_id, column_name, written) AS (VALUES ('21bd525e-fe10-40dd-96be-32d3c8d36d26'::uuid, 'mystery', '7'), ('21bd525e-fe10-40dd-96be-32d3c8d36d26'::uuid, 'total_power', '20'), ('21bd525e-fe10-40dd-96be-32d3c8d36d26'::uuid, 'rarity_score', '35'), ('21bd525e-fe10-40dd-96be-32d3c8d36d26'::uuid, 'rarity_tier', '3'))
SELECT 'journal rows for the rollback stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-10-04f_mechanical-card-stats-rollback'
UNION ALL
SELECT 'planned rows still holding the written value', count(*)::text
  FROM planned p JOIN card_stats t ON t.site_id = p.site_id
 WHERE CASE p.column_name
                WHEN 'antiquity' THEN t.antiquity IS NOT DISTINCT FROM p.written::integer
                WHEN 'fortification' THEN t.fortification IS NOT DISTINCT FROM p.written::integer
                WHEN 'cultural_influence' THEN t.cultural_influence IS NOT DISTINCT FROM p.written::integer
                WHEN 'mystery' THEN t.mystery IS NOT DISTINCT FROM p.written::integer
                WHEN 'legacy' THEN t.legacy IS NOT DISTINCT FROM p.written::integer
                WHEN 'total_power' THEN t.total_power IS NOT DISTINCT FROM p.written::integer
                WHEN 'rarity_score' THEN t.rarity_score IS NOT DISTINCT FROM p.written::integer
                WHEN 'rarity_tier' THEN t.rarity_tier IS NOT DISTINCT FROM p.written::integer
                WHEN 'category_group' THEN t.category_group IS NOT DISTINCT FROM p.written::character varying
                WHEN 'civilization' THEN t.civilization IS NOT DISTINCT FROM p.written::character varying
                WHEN 'empires' THEN t.empires IS NOT DISTINCT FROM p.written::jsonb
                WHEN 'empire_count' THEN t.empire_count IS NOT DISTINCT FROM p.written::integer
                ELSE false END
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
